 lock=json.loads(LOCK.read_text(encoding='utf-8'));plan=json.loads(PLAN.read_text(encoding='utf-8'));sel=json.loads(SEL.read_text(encoding='utf-8'));c1blob=h(C1);b2blob=h(B2)
